2	import { ScriptPropertyCard } from "../../script/entities/ScriptPropertyCard";
3	import type { ReviewableCard } from "../../srs/entities/ReviewableCard";
4	import { VocabCard } from "../../vocabulary/entities/VocabCard";
5	import type {
6		GameCardPool,
7		GameItem,
8		GameItemContent,
9		GameItemSource,
10		GameRoundConfig,
11		RandomSource,
12		SymbolChallengeDirection,
13		WordChallengeDirection,
14	} from "../types";
15	import { itemWeight, type ScheduleStats, worstStats } from "./itemWeight";
16	import { sampleWithoutReplacement } from "./sampling";
17	
18	/**
19	 * `selectRound`'s own config shape: `GameRoundConfig`'s `prioritizeWeakItems`
20	 * made optional here (rather than `Pick`, which would keep it required) so
21	 * every caller that predates weighting — every existing test, and any
22	 * caller that never intends to weight — keeps compiling unchanged.
23	 */
24	type SelectRoundConfig = Pick<GameRoundConfig, "pools" | "itemCount"> & {
25		readonly prioritizeWeakItems?: boolean;
26	};
27	
28	/**
29	 * Composes one `GameItemSource` per pool, samples across them, and assigns
30	 * each drawn item a challenge direction. Adding a pool is adding a source
31	 * to the array; weighting (task 3.1) is supplying `weightOf` to the sample
32	 * when `prioritizeWeakItems` is set — no other behavior changes.
33	 *
34	 * The optional `cardRepository` is read only for weighting, directly (the
35	 * same `easeFactor`/`lapseCount`/`repetitions` fields
36	 * `ReviewService.getCriticalItems` reads) — never through `ReviewService`
37	 * itself, which stays a sibling over the same port, not something this
38	 * service chains through.
39	 */
40	export class GameItemSelectionService {
41		constructor(
42			private readonly sources: readonly GameItemSource[],
43			private readonly cardRepository?: CardRepository,
44		) {}
45	
46		selectRound(
47			config: SelectRoundConfig,
48			rng: RandomSource = Math.random,
49		): GameItem[] {
50			const eligible = this.eligibleContent(config.pools);
51			const weightOf =
52				config.prioritizeWeakItems && this.cardRepository
53					? this.weightOfFor(config.pools)
54					: undefined;
55			const drawn = sampleWithoutReplacement(eligible, config.itemCount, {
56				rng,
57				weightOf,
58			});
59			return drawn.map((content) => assignDirection(content, rng));
60		}
61	
62		private eligibleContent(pools: readonly GameCardPool[]): GameItemContent[] {
63			return this.sources
64				.filter((source) => pools.includes(source.pool))
65				.flatMap((source) => source.eligibleContent());
66		}
67	
68		/**
69		 * One weight per item key (`itemKeyOfCard`/`itemKeyOfContent` below),
70		 * built from every card across the requested pools grouped by that same
71		 * key, each reduced to its worst (lowest ease factor) card's stats
72		 * before scoring. An item with no matching stats (should not happen —
73		 * eligibility itself requires a card) falls back to a neutral weight of
74		 * `1` rather than throwing.
75		 */
76		private weightOfFor(
77			pools: readonly GameCardPool[],
78		): (content: GameItemContent) => number {
79			// Every card's stats, grouped under its item's key — several cards can
80			// share one key (one per PropertyType/VocabProperty), so this collects
81			// them all before `worstStats` below picks the representative one.
82			const statsByKey = new Map<string, ScheduleStats[]>();
83			for (const pool of pools) {
84				for (const card of this.cardRepository?.findAll(pool) ?? []) {
85					const key = itemKeyOfCard(card);
86					if (!key) continue;
87					const stats: ScheduleStats = {
88						easeFactor: card.schedule.easeFactor.value,
89						lapseCount: card.schedule.lapseCount,
90						repetitions: card.schedule.repetitions,
91					};
92					const list = statsByKey.get(key);
93					if (list) list.push(stats);
94					else statsByKey.set(key, [stats]);
95				}
96			}
97	
98			// One weight per key, from its worst card's stats only.
99			const weightByKey = new Map<string, number>();
100			for (const [key, stats] of statsByKey) {
101				const worst = worstStats(stats);
102				if (worst) weightByKey.set(key, itemWeight(worst));
103			}
104	
105			// A key with no cached weight should be unreachable (eligibility
106			// itself requires a card), but a neutral fallback is safer than a
107			// throw a caller would have no reason to expect.
108			return (content) => weightByKey.get(itemKeyOfContent(content)) ?? 1;
109		}
110	}
111	
112	/**
113	 * A card's own item key, mirroring `itemKeyOf` in `PlayGameUseCase.ts` and
114	 * `SymbolGameItemSource`/`WordGameItemSource`'s own eligibility grouping.
115	 * Duplicated rather than imported: neither source exports its dedupe key,
116	 * and this service's own scope does not extend to changing them.
117	 */
118	function itemKeyOfCard(card: ReviewableCard): string | null {
119		if (card instanceof ScriptPropertyCard) {
120			return `symbol:${card.symbolCharacter}`;
121		}
122		if (card instanceof VocabCard) {
123			const [prefix, thai] = card.id.split(":");
124			if (prefix !== "vocab" || !thai) return null;
125			return `word:${thai}`;
126		}
127		return null;
128	}
129	
130	function itemKeyOfContent(content: GameItemContent): string {
131		return content.kind === "symbol"
132			? `symbol:${content.symbolCharacter}`
133			: `word:${content.thaiWord}`;
134	}
135	
136	/**
137	 * An item with no audio can never be asked to hear anything — so it is
138	 * always assigned the direction that needs no audio (`reading` for a
139	 * symbol, `production` for a word), and no randomness is spent on it.
140	 * Otherwise the direction is a 50/50 draw.
141	 */
142	function assignDirection(
143		content: GameItemContent,
144		rng: RandomSource,
145	): GameItem {
146		if (content.kind === "symbol") {
147			const challengeDirection: SymbolChallengeDirection = !content.audioUrl
148				? "reading"
149				: rng() < 0.5
150					? "dictation"
151					: "reading";
152			return { ...content, challengeDirection };
153		}
154	
155		const challengeDirection: WordChallengeDirection = !content.audioUrl
156			? "production"
157			: rng() < 0.5
158				? "dictationTranslate"
159				: "production";
160		return { ...content, challengeDirection };
161	}
