441				// up all-one-kind — this seed is a witness, not a statistical claim.
442				const service = new GameItemSelectionService([
443					sourceOf("script", [
444						symbolContent("s1", "/audio/s1.mp3"),
445						symbolContent("s2", "/audio/s2.mp3"),
