1	import { useCallback, useEffect, useRef, useState } from "react";
2	import type { GameInputMode, WordGameItem } from "../../../domain/game/types";
3	import type { RecallRating } from "../../../domain/shared/types";
4	import {
5		DrawingCanvas,
6		type DrawingCanvasHandle,
7	} from "../atoms/DrawingCanvas";
8	import { RatingButtons } from "./RatingButtons";
9	
10	interface Props {
11		item: WordGameItem;
12		inputMode: GameInputMode;
13		onRate: (rating: RecallRating) => void;
14	}
15	
16	/**
17	 * Hear it, write it: the item's Thai audio plays up front, the learner
18	 * writes the Thai spelling (and, mentally/on paper, the English meaning),
19	 * then reveals both the spelling and the meaning and self-rates.
20	 *
21	 * Reset and autoplay are keyed on the item's own identity (`thaiWord`),
22	 * never on `audioUrl` alone — two consecutive same-direction items reuse
23	 * this component instance without a remount, and two distinct items could
24	 * share an audio file (see CONTEXT.md).
25	 */
26	export function WordDictationChallenge({ item, inputMode, onRate }: Props) {
27		const [revealed, setRevealed] = useState(false);
28		const canvasRef = useRef<DrawingCanvasHandle>(null);
29		const audioRef = useRef<HTMLAudioElement | null>(null);
30	
31		const playAudio = useCallback(() => {
32			if (!item.audioUrl) return;
33			if (audioRef.current) {
34				audioRef.current.pause();
35				audioRef.current.currentTime = 0;
36			}
37			const audio = new Audio(item.audioUrl);
38			audioRef.current = audio;
39			audio.play().catch(() => {});
40		}, [item.audioUrl]);
41	
42		// Reset state and play the prompt audio on item change.
43		// biome-ignore lint/correctness/useExhaustiveDependencies: the item's identity drives reset and autoplay
44		useEffect(() => {
45			setRevealed(false);
46			canvasRef.current?.clear();
47			playAudio();
48			return () => {
49				audioRef.current?.pause();
50				audioRef.current = null;
51			};
52		}, [item.thaiWord]);
53	
54		return (
55			<div className="space-y-6">
56				<div
57					className="rounded-xl p-4"
58					style={{
59						border: "1px solid var(--color-border)",
60						background: "var(--color-surface)",
61					}}
62				>
63					<div className="text-center mb-3">
64						<button
65							type="button"
66							onClick={playAudio}
67							className="inline-flex items-center justify-center w-24 h-24 rounded-full transition-colors text-5xl"
68							style={{
69								background: "var(--color-surface-2)",
70								color: "var(--color-primary)",
71							}}
72							aria-label="Replay pronunciation"
73						>
74							🔊
75						</button>
76					</div>
77	
78					<p
79						className="text-center text-lg mb-4"
80						style={{ color: "var(--color-text-muted)" }}
81					>
82						{inputMode === "draw"
83							? "Listen, then write the Thai spelling and English meaning below"
84							: "Listen, then write the Thai spelling and English meaning on paper"}
85					</p>
86	
87					{inputMode === "draw" && (
88						<div className="flex justify-center">
89							<DrawingCanvas ref={canvasRef} disabled={revealed} />
90						</div>
91					)}
92				</div>
93	
94				{!revealed ? (
95					<button
96						type="button"
97						onClick={() => setRevealed(true)}
98						className="w-full py-4 rounded-xl text-lg font-semibold transition-colors"
99						style={{
100							background: "var(--color-surface-2)",
101							color: "var(--color-text)",
102						}}
103					>
104						Show Answer
105					</button>
106				) : (
107					<div
108						style={{ animation: "slideUp 0.25s ease-out" }}
109						className="space-y-6"
110					>
111						<div
112							className="text-center py-4 rounded-xl"
113							style={{ background: "var(--color-surface-2)" }}
114						>
115							<p
116								className="text-6xl font-bold"
117								style={{ color: "var(--color-primary)" }}
118							>
119								{item.thaiWord}
120							</p>
121							<p
122								className="text-lg mt-2"
